CREATE POLICY avatar_owner_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='avatars' AND (storage.foldername(name))[1]=auth.uid()::text); CREATE POLICY avatar_owner_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='avatars' AND (storage.foldername(name))[1]=auth.uid()::text AND lower(storage.extension(name)) IN ('jpg','jpeg','png','webp')); CREATE POLICY avatar_owner_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='avatars' AND (storage.foldername(name))[1]=auth.uid()::text);